import React from 'react';

const recruiters = [
    "TCS", "Infosys", "Wipro", "Cognizant", "Accenture", "IBM", "L&T", "Amazon", "Oracle", "Cisco"
];

const Placement = () => {
    return (
        <section id="placement" className="py-16 bg-white border-t border-slate-100 mt-2">
            <div className="max-w-7xl mx-auto px-6 lg:px-10">
                <div className="mb-10 text-center">
                    <h2 className="text-[1.75rem] font-display font-bold text-slate-800 mb-4 uppercase tracking-wide">Training & Placement Cell</h2>
                    <div className="w-16 h-1 bg-coral mx-auto"></div>
                </div>

                <div className="bg-slate-50 border border-slate-200 rounded p-8 relative overflow-hidden shadow-sm">
                    <h3 className="text-lg font-bold text-slate-700 text-center mb-8 uppercase tracking-wide">Our Major Recruiters</h3>

                    <style>
                    {`
                    @keyframes slide {
                        0% { transform: translateX(0); }
                        100% { transform: translateX(calc(-120px * 10)); }
                    }
                    .recruiters-track {
                        animation: slide 30s linear infinite;
                    }
                    `}
                    </style>

                    <div className="flex overflow-hidden">
                        <div className="flex gap-6 recruiters-track items-center min-w-max">
                            {[...recruiters, ...recruiters].map((rec, idx) => (
                                <div key={idx} className="w-28 h-12 bg-white flex items-center justify-center rounded border border-slate-200 shadow-sm">
                                    <span className="font-bold text-slate-600 text-sm tracking-wide">{rec}</span>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="mt-10 grid grid-cols-2 md:grid-cols-4 gap-6 text-center border-t border-slate-200 pt-8">
                        <div>
                            <div className="text-[1.5rem] font-bold text-coral mb-1">450+</div>
                            <div className="text-[0.75rem] font-bold text-slate-500 uppercase tracking-wider">Offers in 2024</div>
                        </div>
                        <div>
                            <div className="text-[1.5rem] font-bold text-coral mb-1">60+</div>
                            <div className="text-[0.75rem] font-bold text-slate-500 uppercase tracking-wider">Companies Visited</div>
                        </div>
                        <div>
                            <div className="text-[1.5rem] font-bold text-coral mb-1">14 LPA</div>
                            <div className="text-[0.75rem] font-bold text-slate-500 uppercase tracking-wider">Highest Package</div>
                        </div>
                        <div>
                            <div className="text-[1.5rem] font-bold text-coral mb-1">90%</div>
                            <div className="text-[0.75rem] font-bold text-slate-500 uppercase tracking-wider">Placement Record</div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default Placement;
